CREATE TABLE public.room_access_credentials (participant_id uuid PRIMARY KEY REFERENCES public.participants(id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms(id), key_hash text NOT NULL, UNIQUE (room_id, key_hash));
GRANT ALL ON public.room_access_credentials TO service_role;
ALTER TABLE public.room_access_credentials ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.room_event_credentials (room_id uuid PRIMARY KEY REFERENCES public.rooms(id), topic text NOT NULL DEFAULT ('sw-' || gen_random_uuid()::text || gen_random_uuid()::text));
GRANT ALL ON public.room_event_credentials TO service_role;
ALTER TABLE public.room_event_credentials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.participants ADD COLUMN admission_status text NOT NULL DEFAULT 'pending';
ALTER TABLE public.participants ADD CONSTRAINT participant_admission_status CHECK (admission_status IN ('pending','approved','rejected'));
COMMENT ON COLUMN public.participants.session_token IS 'DEPRECATED: new rooms store only a public participant identifier here; private capability hashes live in room_access_credentials. Legacy keys cannot authorize access.';
COMMENT ON COLUMN public.rooms.host_session IS 'DEPRECATED: new rooms store a public participant identifier, not an authentication credential.';
UPDATE public.player_state SET updated_by = NULL;
CREATE FUNCTION public.sw_key_hash() RETURNS text LANGUAGE sql STABLE SET search_path = public AS $$ SELECT CASE WHEN (coalesce(current_setting('request.headers', true), '{}')::jsonb->>'x-room-key') ~ '^[a-f0-9]{64}$' THEN encode(sha256(convert_to(coalesce(current_setting('request.headers', true), '{}')::jsonb->>'x-room-key','UTF8')),'hex') ELSE NULL END $$;
CREATE FUNCTION public.sw_member_id(_room uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT c.participant_id FROM public.room_access_credentials c JOIN public.participants p ON p.id=c.participant_id WHERE c.room_id=_room AND c.key_hash=public.sw_key_hash() AND p.admission_status='approved' $$;
CREATE FUNCTION public.sw_storage_access(_path text, _write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.room_access_credentials c JOIN public.participants p ON p.id=c.participant_id WHERE c.room_id::text=split_part(_path,'/',1) AND c.key_hash=public.sw_key_hash() AND p.admission_status='approved' AND (NOT _write OR c.participant_id::text=split_part(_path,'/',2))) $$;
REVOKE ALL ON FUNCTION public.sw_key_hash(), public.sw_member_id(uuid), public.sw_storage_access(text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.sw_key_hash(), public.sw_member_id(uuid), public.sw_storage_access(text,boolean) TO anon, authenticated, service_role;
DROP POLICY "participants readable" ON public.participants;
DROP POLICY "participants insertable" ON public.participants;
DROP POLICY "participants updatable" ON public.participants;
DROP POLICY "participants deletable" ON public.participants;
REVOKE ALL ON public.participants FROM anon, authenticated;
DROP POLICY "player_state readable" ON public.player_state;
DROP POLICY "player_state insertable" ON public.player_state;
DROP POLICY "player_state updatable" ON public.player_state;
REVOKE INSERT, UPDATE, DELETE ON public.player_state FROM anon, authenticated;
CREATE POLICY "Approved room members read playback" ON public.player_state FOR SELECT TO anon, authenticated USING (public.sw_member_id(room_id) IS NOT NULL);
DROP POLICY "messages readable" ON public.messages;
DROP POLICY "messages insertable" ON public.messages;
REVOKE INSERT, UPDATE, DELETE ON public.messages FROM anon, authenticated;
CREATE POLICY "Approved room members read chat" ON public.messages FOR SELECT TO anon, authenticated USING (public.sw_member_id(room_id) IS NOT NULL);
DROP POLICY "room videos readable" ON storage.objects;
DROP POLICY "room videos uploadable" ON storage.objects;
CREATE POLICY "Approved viewers read their room videos" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id='room-videos' AND public.sw_storage_access(name));
CREATE POLICY "Viewers upload into their own room folder" ON storage.objects FOR INSERT TO anon, authenticated WITH CHECK (bucket_id='room-videos' AND public.sw_storage_access(name,true));
CREATE POLICY "Viewers resume only their own uploads" ON storage.objects FOR UPDATE TO anon, authenticated USING (bucket_id='room-videos' AND public.sw_storage_access(name,true)) WITH CHECK (bucket_id='room-videos' AND public.sw_storage_access(name,true));
CREATE FUNCTION public.sw_create(_code text, _name text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE r uuid := gen_random_uuid(); p uuid := gen_random_uuid(); h text := public.sw_key_hash(); BEGIN IF h IS NULL OR _code !~ '^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{6}$' OR char_length(trim(_name)) NOT BETWEEN 1 AND 24 THEN RAISE EXCEPTION 'Invalid request'; END IF; INSERT INTO public.rooms(id,code,host_session) VALUES(r,_code,p::text); INSERT INTO public.participants(id,room_id,session_token,display_name,is_host,admission_status) VALUES(p,r,p::text,trim(_name),true,'approved'); INSERT INTO public.room_access_credentials VALUES(p,r,h); INSERT INTO public.room_event_credentials(room_id) VALUES(r); INSERT INTO public.player_state(room_id) VALUES(r); RETURN jsonb_build_object('room_id',r,'code',_code); END $$;
CREATE FUNCTION public.sw_enter(_code text, _name text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE r uuid; p uuid; h text := public.sw_key_hash(); BEGIN IF h IS NULL OR char_length(trim(_name)) NOT BETWEEN 1 AND 24 THEN RAISE EXCEPTION 'Invalid request'; END IF; SELECT id INTO r FROM public.rooms WHERE code=upper(_code); IF r IS NULL THEN RETURN jsonb_build_object('status','missing'); END IF; IF NOT EXISTS(SELECT 1 FROM public.room_event_credentials WHERE room_id=r) THEN RETURN jsonb_build_object('status','legacy'); END IF; PERFORM 1 FROM public.rooms WHERE id=r FOR UPDATE; SELECT participant_id INTO p FROM public.room_access_credentials WHERE room_id=r AND key_hash=h; IF p IS NULL THEN IF (SELECT count(*) FROM public.participants WHERE room_id=r AND admission_status='pending') >= 100 THEN RAISE EXCEPTION 'Room queue full'; END IF; p:=gen_random_uuid(); INSERT INTO public.participants(id,room_id,session_token,display_name,admission_status) VALUES(p,r,p::text,trim(_name),'pending'); INSERT INTO public.room_access_credentials VALUES(p,r,h); END IF; RETURN jsonb_build_object('room_id',r); END $$;
CREATE FUNCTION public.sw_snapshot(_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE r uuid; p uuid; s text; topic text; viewers jsonb; pending jsonb; playback jsonb; BEGIN SELECT id INTO r FROM public.rooms WHERE code=upper(_code); IF r IS NULL THEN RETURN jsonb_build_object('status','missing'); END IF; IF NOT EXISTS(SELECT 1 FROM public.room_event_credentials WHERE room_id=r) THEN RETURN jsonb_build_object('status','legacy'); END IF; SELECT c.participant_id,v.admission_status INTO p,s FROM public.room_access_credentials c JOIN public.participants v ON v.id=c.participant_id WHERE c.room_id=r AND c.key_hash=public.sw_key_hash(); IF p IS NULL THEN RETURN jsonb_build_object('status','unknown'); END IF; IF s <> 'approved' THEN RETURN jsonb_build_object('status',s,'room_id',r,'member_id',p); END IF; SELECT e.topic INTO topic FROM public.room_event_credentials e WHERE e.room_id=r; SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'display_name',display_name,'color',color,'is_host',is_host,'last_seen_at',last_seen_at) ORDER BY created_at),'[]') INTO viewers FROM public.participants WHERE room_id=r AND admission_status='approved'; SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'display_name',display_name) ORDER BY created_at),'[]') INTO pending FROM public.participants WHERE room_id=r AND admission_status='pending'; SELECT to_jsonb(ps) INTO playback FROM public.player_state ps WHERE room_id=r; RETURN jsonb_build_object('status',s,'room_id',r,'member_id',p,'topic',topic,'participants',viewers,'requests',pending,'state',playback,'server_time',now()); END $$;
CREATE FUNCTION public.sw_review(_room uuid, _participant uuid, _approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF public.sw_member_id(_room) IS NULL THEN RAISE EXCEPTION 'Room approval required' USING ERRCODE='42501'; END IF; UPDATE public.participants SET admission_status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END WHERE id=_participant AND room_id=_room AND admission_status='pending'; END $$;
CREATE FUNCTION public.sw_heartbeat(_room uuid, _leaving boolean DEFAULT false, _position double precision DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p uuid := public.sw_member_id(_room); was_idle boolean; BEGIN IF p IS NULL THEN RAISE EXCEPTION 'Room approval required' USING ERRCODE='42501'; END IF; PERFORM 1 FROM public.rooms WHERE id=_room FOR UPDATE; SELECT NOT EXISTS(SELECT 1 FROM public.participants WHERE room_id=_room AND admission_status='approved' AND last_seen_at>now()-interval '90 seconds' AND (NOT _leaving OR id<>p)) INTO was_idle; IF _leaving AND was_idle THEN UPDATE public.player_state SET is_playing=false, position_seconds=CASE WHEN _position>=0 AND _position<'Infinity'::float8 THEN _position ELSE position_seconds END, updated_by=p::text WHERE room_id=_room; ELSIF NOT _leaving AND was_idle THEN UPDATE public.player_state SET is_playing=false, updated_by=p::text WHERE room_id=_room; END IF; UPDATE public.participants SET last_seen_at=CASE WHEN _leaving THEN now()-interval '1 day' ELSE now() END WHERE id=p; END $$;
CREATE FUNCTION public.sw_playback(_room uuid, _patch jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p uuid := public.sw_member_id(_room); result jsonb; src text; ref text; pos double precision; BEGIN IF p IS NULL THEN RAISE EXCEPTION 'Room approval required' USING ERRCODE='42501'; END IF; IF _patch ? 'source_type' THEN src:=_patch->>'source_type'; ref:=_patch->>'source_ref'; IF src NOT IN ('none','youtube','vimeo','file','upload','other') OR char_length(coalesce(ref,''))>4000 THEN RAISE EXCEPTION 'Invalid source'; END IF; IF src IN ('file','other') AND ref !~ '^https?://' THEN RAISE EXCEPTION 'Invalid link'; END IF; IF src='upload' AND (NOT public.sw_storage_access(ref) OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='room-videos' AND name=ref)) THEN RAISE EXCEPTION 'Invalid room video' USING ERRCODE='42501'; END IF; END IF; IF _patch ? 'position_seconds' THEN pos:=(_patch->>'position_seconds')::double precision; IF pos IS NULL OR pos<0 OR NOT pos<'Infinity'::float8 THEN RAISE EXCEPTION 'Invalid position'; END IF; END IF; UPDATE public.player_state SET source_type=CASE WHEN _patch ? 'source_type' THEN src ELSE source_type END, source_ref=CASE WHEN _patch ? 'source_type' THEN ref ELSE source_ref END, source_title=CASE WHEN _patch ? 'source_type' THEN left(_patch->>'source_title',300) ELSE source_title END, is_playing=CASE WHEN _patch ? 'is_playing' THEN (_patch->>'is_playing')::boolean ELSE is_playing END, position_seconds=CASE WHEN _patch ? 'position_seconds' THEN pos ELSE position_seconds END, updated_by=p::text WHERE room_id=_room RETURNING to_jsonb(player_state.*) INTO result; RETURN result; END $$;
CREATE FUNCTION public.sw_message(_room uuid, _body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p uuid := public.sw_member_id(_room); BEGIN IF p IS NULL THEN RAISE EXCEPTION 'Room approval required' USING ERRCODE='42501'; END IF; IF char_length(trim(_body)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Invalid message'; END IF; INSERT INTO public.messages(room_id,display_name,color,body) SELECT _room,display_name,color,trim(_body) FROM public.participants WHERE id=p; END $$;
CREATE FUNCTION public.sw_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE topic text; BEGIN IF TG_TABLE_NAME='participants' AND TG_OP='UPDATE' AND NEW.admission_status=OLD.admission_status AND NEW.display_name=OLD.display_name THEN RETURN NEW; END IF; SELECT e.topic INTO topic FROM public.room_event_credentials e WHERE e.room_id=NEW.room_id; IF topic IS NOT NULL THEN PERFORM realtime.send('{}'::jsonb,'changed',topic,false); END IF; RETURN NEW; END $$;
CREATE TRIGGER sw_participant_notify AFTER INSERT OR UPDATE ON public.participants FOR EACH ROW EXECUTE FUNCTION public.sw_notify();
CREATE TRIGGER sw_playback_notify AFTER UPDATE ON public.player_state FOR EACH ROW EXECUTE FUNCTION public.sw_notify();
CREATE TRIGGER sw_message_notify AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.sw_notify();
REVOKE ALL ON FUNCTION public.sw_notify() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.sw_create(text,text), public.sw_enter(text,text), public.sw_snapshot(text), public.sw_review(uuid,uuid,boolean), public.sw_heartbeat(uuid,boolean,double precision), public.sw_playback(uuid,jsonb), public.sw_message(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.sw_create(text,text), public.sw_enter(text,text), public.sw_snapshot(text), public.sw_review(uuid,uuid,boolean), public.sw_heartbeat(uuid,boolean,double precision), public.sw_playback(uuid,jsonb), public.sw_message(uuid,text) TO anon, authenticated;